<div class="heading"><h2>پروفایل اختصاصی شهید</h2><a class="outline" href="<?= e(url('gallery')) ?>">بازگشت به تصاویر</a></div><div class="profile"><aside><?php if($images): ?><img src="<?= e(url('media',['id'=>$images[0]['id']])) ?>" alt="<?= e($m['first_name'].' '.$m['last_name']) ?>"><?php endif ?><h2>شهید <?= e($m['first_name'].' '.$m['last_name']) ?></h2><p class="muted">کد: <?= e($m['code']) ?></p><?php foreach(['father_name'=>'نام پدر','birth_date'=>'تولد','death_date'=>'شهادت','province'=>'استان','city'=>'شهر','job'=>'شغل','organization'=>'سازمان','burial_place'=>'محل دفن'] as $key=>$label): ?><?php if($m[$key]!==''): ?><p><?= $label ?>: <?= e($m[$key]) ?></p><?php endif ?><?php endforeach ?><p class="prose"><?= e($m['summary']) ?></p></aside><section><h2>تصاویر و آثار این شهید</h2><?php view('cards',compact('images')); ?><?php foreach(['biography'=>'زندگی‌نامه کامل','will_text'=>'وصیت‌نامه','memories'=>'خاطرات'] as $key=>$label): ?><details><summary><?= $label ?></summary><p class="prose"><?= e($m[$key]?:'هنوز اطلاعاتی ثبت نشده است.') ?></p></details><?php endforeach ?></section></div>
